-- Generated source mirror; execute only in an admitted ECS database.
CREATE TABLE IF NOT EXISTS runtime_state (
 legacy_clock_json JSON NULL,
 namespace VARCHAR(64) COLLATE utf8mb4_bin NOT NULL,
 owner_id BIGINT NOT NULL,
 scope_key VARCHAR(160) COLLATE utf8mb4_bin NOT NULL DEFAULT '',
 session_id VARCHAR(160) COLLATE utf8mb4_bin NULL,
 state_key VARCHAR(160) COLLATE utf8mb4_bin NULL,
 revision BIGINT NOT NULL DEFAULT 0,
 state_code VARCHAR(32) COLLATE utf8mb4_bin NULL,
 current_ref VARCHAR(180) COLLATE utf8mb4_bin NULL,
 counter_value BIGINT NULL,
 provider VARCHAR(24) COLLATE utf8mb4_bin NULL,
 credential_sha256 CHAR(64) COLLATE utf8mb4_bin NULL,
 actor_user_id BIGINT NULL,
 request_id VARCHAR(128) COLLATE utf8mb4_bin NULL,
 window_started_at DATETIME(6) NULL,
 window_ends_at DATETIME(6) NULL,
 payload_version SMALLINT NOT NULL DEFAULT 1,
 payload_json LONGTEXT NULL,
 created_at DATETIME(6) NULL,
 updated_at DATETIME(6) NULL DEFAULT (UTC_TIMESTAMP(6)),
 PRIMARY KEY (namespace,owner_id,scope_key),
 UNIQUE KEY uk_runtime_sdk_slot (namespace,owner_id,session_id,state_key),
 CONSTRAINT ck_runtime_owner CHECK (owner_id>=0),
 CONSTRAINT ck_runtime_revision CHECK (revision>=0),
 CONSTRAINT ck_runtime_counter CHECK (counter_value IS NULL OR counter_value>=0),
 CONSTRAINT ck_runtime_updated CHECK (((namespace='RESEARCH_EXPORT_LIMIT' OR (updated_at IS NOT NULL OR legacy_clock_json IS NOT NULL) OR (namespace IN ('CONTEXT_HEAD','CONTEXT_BOOTSTRAP') AND created_at IS NULL AND payload_json IS NOT NULL AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacySource'))=CASE namespace WHEN 'CONTEXT_HEAD' THEN 'agent_context_head' ELSE 'agent_context_bootstrap' END) OR (namespace='DETECTION_CREATION_OWNER' AND created_at IS NULL AND payload_version=1 AND payload_json IS NOT NULL AND JSON_LENGTH(payload_json)=1 AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.legacySource'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacySource'))=BINARY 'detection_creation_owner')) OR (created_at IS NULL AND payload_json IS NOT NULL AND payload_version=1 AND ((namespace='DETECTION_IDENTITY_CONTROL' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacySource'))=BINARY 'detection_identity_control') OR (namespace='DETECTION_IDENTITY_SOURCE_CONTROL' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacySource'))=BINARY 'detection_identity_source_control') OR (namespace='DETECTION_IDENTITY_BINDING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacySource'))=BINARY 'detection_identity_binding')))) OR (namespace IN ('RESEARCH_STORAGE','SKILL_DOWNLOAD') AND owner_id>0 AND scope_key='' AND revision=0 AND payload_json IS NULL AND state_code IS NULL AND current_ref IS NULL AND counter_value IS NULL)),
 CONSTRAINT ck_runtime_payload_version CHECK (payload_version>0),
 CONSTRAINT ck_runtime_payload CHECK (payload_json IS NULL OR (JSON_VALID(payload_json) AND JSON_TYPE(CAST(payload_json AS JSON))='OBJECT')),
 CONSTRAINT ck_runtime_sdk CHECK ((namespace='SDK_CHECKPOINT' AND owner_id>0 AND session_id IS NOT NULL AND state_key IS NOT NULL AND CHAR_LENGTH(state_key)<=128 AND CHAR_LENGTH(scope_key)=64 AND revision>0 AND payload_version=1 AND payload_json IS NOT NULL) OR (namespace IN ('CONTEXT_HEAD','CONTEXT_BOOTSTRAP') AND owner_id>0 AND session_id IS NOT NULL AND state_key IS NOT NULL AND CHAR_LENGTH(scope_key)=64 AND payload_version=1 AND payload_json IS NOT NULL) OR (namespace NOT IN ('SDK_CHECKPOINT','CONTEXT_HEAD','CONTEXT_BOOTSTRAP') AND session_id IS NULL AND state_key IS NULL)),
 CONSTRAINT ck_runtime_model_control CHECK (namespace<>'MODEL_CONFIG_CONTROL' OR (owner_id=0 AND scope_key='GLOBAL' AND state_code IS NOT NULL AND state_code='READY' AND counter_value IS NOT NULL AND current_ref IS NOT NULL AND current_ref REGEXP '^(0|[1-9][0-9]{0,18})$' AND CAST(current_ref AS DECIMAL(20,0))<=counter_value AND payload_json IS NULL AND window_started_at IS NULL AND window_ends_at IS NULL)),
 CONSTRAINT ck_runtime_key_revocation CHECK ((namespace='MODEL_KEY_REVOCATION' AND owner_id=0 AND state_code IS NOT NULL AND state_code='REVOKED' AND provider IS NOT NULL AND provider IN ('dashscope','deepseek','openai') AND credential_sha256 IS NOT NULL AND credential_sha256 REGEXP '^[a-f0-9]{64}$' AND scope_key=CONCAT(provider,':',credential_sha256) AND actor_user_id IS NOT NULL AND actor_user_id>0 AND request_id IS NOT NULL AND CHAR_LENGTH(request_id)>0 AND counter_value IS NOT NULL AND counter_value IN (0,1) AND (created_at IS NOT NULL OR legacy_clock_json IS NOT NULL) AND current_ref IS NULL AND payload_json IS NULL AND window_started_at IS NULL AND window_ends_at IS NULL) OR (namespace<>'MODEL_KEY_REVOCATION' AND provider IS NULL AND credential_sha256 IS NULL AND actor_user_id IS NULL AND request_id IS NULL)),
 CONSTRAINT ck_runtime_research_export_limit CHECK (namespace<>'RESEARCH_EXPORT_LIMIT' OR (owner_id>0 AND scope_key='' AND revision=0 AND counter_value IS NOT NULL AND (window_ends_at IS NOT NULL OR legacy_clock_json IS NOT NULL) AND window_started_at IS NULL AND state_code IS NULL AND current_ref IS NULL AND payload_json IS NULL AND created_at IS NULL AND updated_at IS NULL)),
 CONSTRAINT ck_runtime_memory_preference CHECK (namespace<>'MEMORY_PREFERENCE' OR (owner_id>0 AND scope_key='' AND state_code IS NULL AND current_ref IS NULL AND counter_value IS NULL AND window_started_at IS NULL AND window_ends_at IS NULL AND created_at IS NULL AND payload_version=1 AND payload_json IS NOT NULL AND JSON_LENGTH(payload_json)=2 AND JSON_EXTRACT(payload_json,'$.readEnabled') IS NOT NULL AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.readEnabled'))='BOOLEAN' AND JSON_EXTRACT(payload_json,'$.saveEnabled') IS NOT NULL AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.saveEnabled'))='BOOLEAN')),
 KEY ix_runtime_state (namespace,state_code,owner_id),
 CONSTRAINT ck_runtime_context_head CHECK (namespace<>'CONTEXT_HEAD' OR (payload_version=1 AND JSON_LENGTH(payload_json)=1 AND JSON_CONTAINS_PATH(payload_json,'all','$.legacySource')=1 AND (JSON_TYPE(JSON_EXTRACT(payload_json,'$.legacySource'))='NULL' OR JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacySource'))='agent_context_head') AND state_code IS NULL AND counter_value IS NULL)),
 CONSTRAINT ck_runtime_context_bootstrap CHECK (namespace<>'CONTEXT_BOOTSTRAP' OR (payload_version=1 AND JSON_LENGTH(payload_json)=4 AND JSON_CONTAINS_PATH(payload_json,'all','$.agentScope','$.initialState','$.initialSha256','$.legacySource')=1 AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.agentScope'))='STRING' AND CHAR_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.agentScope')))<=160 AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.initialState'))='STRING' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.initialSha256')) REGEXP '^[a-fA-F0-9]{64}$' AND (JSON_TYPE(JSON_EXTRACT(payload_json,'$.legacySource'))='NULL' OR JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacySource'))='agent_context_bootstrap') AND counter_value IS NOT NULL AND state_code IN ('RESERVED','INITIALIZED'))),
 CONSTRAINT ck_runtime_mcp_retention CHECK (namespace<>'MCP_RETENTION_CONTROL' OR (owner_id=0 AND scope_key REGEXP '^-?[0-9]{1,3}$' AND CAST(scope_key AS SIGNED) BETWEEN -128 AND 127 AND state_code IS NOT NULL AND state_code IN ('COLLECTING','ACTIVE') AND payload_json IS NULL AND current_ref IS NULL AND counter_value IS NULL)),
 CONSTRAINT ck_detection_creation_owner CHECK (namespace<>'DETECTION_CREATION_OWNER' OR (
   owner_id>0 AND scope_key='' AND revision=0 AND session_id IS NULL AND state_key IS NULL
   AND state_code IS NULL AND current_ref IS NULL AND counter_value IS NULL
   AND ((payload_json IS NULL AND (created_at IS NOT NULL OR legacy_clock_json IS NOT NULL) AND (updated_at IS NOT NULL OR legacy_clock_json IS NOT NULL))
     OR (payload_version=1 AND JSON_LENGTH(payload_json)=1
       AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.legacySource'))='STRING'
       AND BINARY JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacySource'))=BINARY 'detection_creation_owner'
       AND created_at IS NULL AND updated_at IS NULL)))),
 identity_task_id VARCHAR(128) COLLATE utf8mb4_bin GENERATED ALWAYS AS (CASE WHEN namespace IN ('DETECTION_IDENTITY_CONTROL','DETECTION_IDENTITY_SOURCE_CONTROL','DETECTION_IDENTITY_BINDING') THEN CASE WHEN JSON_TYPE(JSON_EXTRACT(payload_json,'$.taskId'))='STRING' THEN JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.taskId')) END END) VIRTUAL,
 identity_role VARCHAR(24) COLLATE utf8mb4_bin GENERATED ALWAYS AS (CASE WHEN namespace IN ('DETECTION_IDENTITY_CONTROL','DETECTION_IDENTITY_SOURCE_CONTROL','DETECTION_IDENTITY_BINDING') THEN CASE WHEN JSON_TYPE(JSON_EXTRACT(payload_json,'$.identityRole'))='STRING' THEN JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.identityRole')) END END) VIRTUAL,
 identity_head_event_ref VARCHAR(180) COLLATE utf8mb4_bin GENERATED ALWAYS AS (CASE WHEN namespace='DETECTION_IDENTITY_BINDING' THEN current_ref END) VIRTUAL,
 UNIQUE KEY uk_identity_binding (namespace,identity_task_id,identity_role),
 UNIQUE KEY uk_identity_head_event (namespace,identity_head_event_ref),
 CONSTRAINT ck_id_runtime_identity_control CHECK (namespace<>'DETECTION_IDENTITY_CONTROL' OR COALESCE((payload_version=1 AND JSON_TYPE(CAST(payload_json AS JSON))='OBJECT' AND JSON_LENGTH(payload_json)=3 AND JSON_CONTAINS_PATH(payload_json,'all','$.controlId','$.activationRevision','$.legacySource')=1 AND (JSON_TYPE(JSON_EXTRACT(payload_json,'$.controlId'))='INTEGER' AND CAST(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.controlId')) AS DECIMAL(20,0)) BETWEEN -2147483648 AND 2147483647) AND (JSON_TYPE(JSON_EXTRACT(payload_json,'$.activationRevision'))='NULL' OR (JSON_TYPE(JSON_EXTRACT(payload_json,'$.activationRevision'))='INTEGER' AND CAST(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.activationRevision')) AS DECIMAL(20,0)) BETWEEN -9223372036854775808 AND 9223372036854775807)) AND (JSON_TYPE(JSON_EXTRACT(payload_json,'$.legacySource'))='NULL' OR (JSON_TYPE(JSON_EXTRACT(payload_json,'$.legacySource'))='STRING' AND CHAR_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacySource')))<=64 AND BINARY JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacySource'))=BINARY 'detection_identity_control'))),0)=1),
 CONSTRAINT ck_id_runtime_identity_source_control CHECK (namespace<>'DETECTION_IDENTITY_SOURCE_CONTROL' OR COALESCE((payload_version=1 AND JSON_TYPE(CAST(payload_json AS JSON))='OBJECT' AND JSON_LENGTH(payload_json)=3 AND JSON_CONTAINS_PATH(payload_json,'all','$.controlId','$.activationRevision','$.legacySource')=1 AND (JSON_TYPE(JSON_EXTRACT(payload_json,'$.controlId'))='INTEGER' AND CAST(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.controlId')) AS DECIMAL(20,0)) BETWEEN -2147483648 AND 2147483647) AND (JSON_TYPE(JSON_EXTRACT(payload_json,'$.activationRevision'))='NULL' OR (JSON_TYPE(JSON_EXTRACT(payload_json,'$.activationRevision'))='INTEGER' AND CAST(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.activationRevision')) AS DECIMAL(20,0)) BETWEEN -9223372036854775808 AND 9223372036854775807)) AND (JSON_TYPE(JSON_EXTRACT(payload_json,'$.legacySource'))='NULL' OR (JSON_TYPE(JSON_EXTRACT(payload_json,'$.legacySource'))='STRING' AND CHAR_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacySource')))<=64 AND BINARY JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacySource'))=BINARY 'detection_identity_source_control'))),0)=1),
 CONSTRAINT ck_id_runtime_identity_binding CHECK (namespace<>'DETECTION_IDENTITY_BINDING' OR COALESCE((payload_version=1 AND JSON_TYPE(CAST(payload_json AS JSON))='OBJECT' AND JSON_LENGTH(payload_json)=6 AND JSON_CONTAINS_PATH(payload_json,'all','$.taskId','$.identityRole','$.eventSha256','$.legacyId','$.legacyEventId','$.legacySource')=1 AND (JSON_TYPE(JSON_EXTRACT(payload_json,'$.taskId'))='STRING' AND CHAR_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.taskId')))<=128) AND (JSON_TYPE(JSON_EXTRACT(payload_json,'$.identityRole'))='STRING' AND CHAR_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.identityRole')))<=24) AND (JSON_TYPE(JSON_EXTRACT(payload_json,'$.eventSha256'))='STRING' AND CHAR_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.eventSha256')))<=64) AND (JSON_TYPE(JSON_EXTRACT(payload_json,'$.legacyId'))='NULL' OR (JSON_TYPE(JSON_EXTRACT(payload_json,'$.legacyId'))='STRING' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacyId')) REGEXP '^(0|[1-9][0-9]{0,19})$' AND CAST(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacyId')) AS DECIMAL(20,0))<=18446744073709551615)) AND (JSON_TYPE(JSON_EXTRACT(payload_json,'$.legacyEventId'))='NULL' OR (JSON_TYPE(JSON_EXTRACT(payload_json,'$.legacyEventId'))='STRING' AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacyEventId')) REGEXP '^(0|[1-9][0-9]{0,19})$' AND CAST(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacyEventId')) AS DECIMAL(20,0))<=18446744073709551615)) AND (JSON_TYPE(JSON_EXTRACT(payload_json,'$.legacySource'))='NULL' OR (JSON_TYPE(JSON_EXTRACT(payload_json,'$.legacySource'))='STRING' AND CHAR_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacySource')))<=64 AND BINARY JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.legacySource'))=BINARY 'detection_identity_binding'))),0)=1),
 CONSTRAINT ck_runtime_fingerprint CHECK (namespace<>'DETECTION_FINGERPRINT' OR COALESCE((namespace='DETECTION_FINGERPRINT' AND owner_id=0 AND scope_key REGEXP '^[a-f0-9]{64}$' AND payload_version=1 AND payload_json IS NOT NULL AND COALESCE(JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"required":["originalId","sourceOwnerKey"],"properties":{"originalId":{"type":"integer","minimum":1,"maximum":9223372036854775807},"sourceOwnerKey":{"type":["string","null"],"maxLength":64}}}',payload_json),0)=1 AND revision<=2147483647 AND state_code IS NOT NULL AND CHAR_LENGTH(state_code)<=32 AND (current_ref IS NULL OR CHAR_LENGTH(current_ref)<=64)),0)=1),
 CONSTRAINT ck_runtime_digest_control CHECK (namespace<>'DIGEST_CONTROL' OR (owner_id=0 AND scope_key='1' AND revision=0 AND payload_json IS NULL AND state_code IS NULL AND current_ref IS NULL AND counter_value IS NULL AND created_at IS NULL)),
 CONSTRAINT ck_legacy_clock_shape_runtime_state CHECK (legacy_clock_json IS NULL OR COALESCE(JSON_SCHEMA_VALID('{"anyOf":[{"type":"object","additionalProperties":false,"required":["protocol","status","sourceTable","sourceKey","sourceSnapshotSha256","sourceRowSha256","sourceWallTimes"],"properties":{"protocol":{"enum":["doorhandle-legacy-clock-v1"]},"status":{"enum":["UNRESOLVED"]},"sourceTable":{"enum":["agent_fetch_image_retention_control"]},"sourceKey":{"type":"object","additionalProperties":false,"required":["control_id"],"properties":{"control_id":{"type":"integer","minimum":-9223372036854775808,"maximum":9223372036854775807}}},"sourceSnapshotSha256":{"type":"string","pattern":"^[a-f0-9]{64}$"},"sourceRowSha256":{"type":"string","pattern":"^[a-f0-9]{64}$"},"sourceWallTimes":{"type":"object","additionalProperties":false,"required":["updated_at"],"properties":{"updated_at":{"type":["string","null"],"pattern":"^[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}(\\\\.[0-9]{1,6})?$"}}}}},{"type":"object","additionalProperties":false,"required":["protocol","status","sourceTable","sourceKey","sourceSnapshotSha256","sourceRowSha256","sourceWallTimes"],"properties":{"protocol":{"enum":["doorhandle-legacy-clock-v1"]},"status":{"enum":["UNRESOLVED"]},"sourceTable":{"enum":["agent_memory_preference"]},"sourceKey":{"type":"object","additionalProperties":false,"required":["owner_user_id"],"properties":{"owner_user_id":{"type":"integer","minimum":-9223372036854775808,"maximum":9223372036854775807}}},"sourceSnapshotSha256":{"type":"string","pattern":"^[a-f0-9]{64}$"},"sourceRowSha256":{"type":"string","pattern":"^[a-f0-9]{64}$"},"sourceWallTimes":{"type":"object","additionalProperties":false,"required":["updated_at"],"properties":{"updated_at":{"type":["string","null"],"pattern":"^[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}(\\\\.[0-9]{1,6})?$"}}}}},{"type":"object","additionalProperties":false,"required":["protocol","status","sourceTable","sourceKey","sourceSnapshotSha256","sourceRowSha256","sourceWallTimes"],"properties":{"protocol":{"enum":["doorhandle-legacy-clock-v1"]},"status":{"enum":["UNRESOLVED"]},"sourceTable":{"enum":["agent_workbench_sdk_state"]},"sourceKey":{"type":"object","additionalProperties":false,"required":["id"],"properties":{"id":{"type":"integer","minimum":0,"maximum":18446744073709551615}}},"sourceSnapshotSha256":{"type":"string","pattern":"^[a-f0-9]{64}$"},"sourceRowSha256":{"type":"string","pattern":"^[a-f0-9]{64}$"},"sourceWallTimes":{"type":"object","additionalProperties":false,"required":["updated_at"],"properties":{"updated_at":{"type":["string","null"],"pattern":"^[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}(\\\\.[0-9]{1,6})?$"}}}}},{"type":"object","additionalProperties":false,"required":["protocol","status","sourceTable","sourceKey","sourceSnapshotSha256","sourceRowSha256","sourceWallTimes"],"properties":{"protocol":{"enum":["doorhandle-legacy-clock-v1"]},"status":{"enum":["UNRESOLVED"]},"sourceTable":{"enum":["detection_report_event_state"]},"sourceKey":{"type":"object","additionalProperties":false,"required":["report_id"],"properties":{"report_id":{"type":"string"}}},"sourceSnapshotSha256":{"type":"string","pattern":"^[a-f0-9]{64}$"},"sourceRowSha256":{"type":"string","pattern":"^[a-f0-9]{64}$"},"sourceWallTimes":{"type":"object","additionalProperties":false,"required":["updated_at"],"properties":{"updated_at":{"type":["string","null"],"pattern":"^[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}(\\\\.[0-9]{1,6})?$"}}}}}]}',legacy_clock_json),0)=1),
 CONSTRAINT ck_legacy_clock_binding_runtime_state CHECK (legacy_clock_json IS NULL OR COALESCE((((BINARY JSON_UNQUOTE(JSON_EXTRACT(legacy_clock_json,'$.sourceTable'))=BINARY 'agent_fetch_image_retention_control') AND (BINARY namespace=BINARY 'MCP_RETENTION_CONTROL') AND (BINARY scope_key<=>BINARY CAST(CAST(JSON_UNQUOTE(JSON_EXTRACT(legacy_clock_json,'$.sourceKey.control_id')) AS DECIMAL(20,0)) AS CHAR))) OR ((BINARY JSON_UNQUOTE(JSON_EXTRACT(legacy_clock_json,'$.sourceTable'))=BINARY 'agent_memory_preference') AND (BINARY namespace=BINARY 'MEMORY_PREFERENCE') AND (BINARY owner_id<=>BINARY CAST(JSON_UNQUOTE(JSON_EXTRACT(legacy_clock_json,'$.sourceKey.owner_user_id')) AS DECIMAL(20,0)))) OR ((BINARY JSON_UNQUOTE(JSON_EXTRACT(legacy_clock_json,'$.sourceTable'))=BINARY 'agent_workbench_sdk_state') AND (BINARY namespace=BINARY 'SDK_CHECKPOINT')) OR ((BINARY JSON_UNQUOTE(JSON_EXTRACT(legacy_clock_json,'$.sourceTable'))=BINARY 'detection_report_event_state') AND (BINARY namespace=BINARY 'REPORT_EVENT_STATE') AND (BINARY scope_key<=>BINARY JSON_UNQUOTE(JSON_EXTRACT(legacy_clock_json,'$.sourceKey.report_id'))))),0)=1)
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
